// Générateur de paquets .apk v2 pour les tests (apk-v2(5), abuild) : membres gzip concaténés,
// [signature] + contrôle (tar sans blocs de fin : `.PKGINFO`, scripts) + données (tar complet).
// `datahash` est le sha256 du membre données compressé ; chaque partie peut être remplacée.

import { createHash } from 'node:crypto';
import { gzipSync } from 'node:zlib';
import { buildTar, type TarSpec } from './tar.js';

export const DEFAULT_PKGINFO: readonly (readonly [string, string])[] = [
  ['pkgname', 'hello'],
  ['pkgver', '2.10-r3'],
  ['pkgdesc', 'Programme de démonstration'],
  ['url', 'https://example.org'],
  ['builddate', '1700000000'],
  ['packager', 'Equipe Test <test@example.org>'],
  ['size', '42'],
  ['arch', 'x86_64'],
  ['origin', 'hello-src'],
  ['commit', '0123456789abcdef'],
  ['maintainer', 'Equipe Test <test@example.org>'],
  ['license', 'MIT'],
  ['depend', 'so:libc.musl-x86_64.so.1'],
  ['depend', 'busybox>=1.36'],
  ['depend', '!hello-old'],
  ['provides', 'cmd:hello=2.10-r3'],
  ['replaces', 'hello-legacy'],
  ['install_if', 'hello-base=2.10-r3 locale'],
];

export const DEFAULT_DATA: readonly TarSpec[] = [
  { path: 'usr/', type: '5', mode: 0o755 },
  { path: 'usr/bin/', type: '5', mode: 0o755 },
  { path: 'usr/bin/hello', data: '#!/bin/sh\necho bonjour\n', mode: 0o755 },
];

export interface ApkSpec {
  /** Lignes de .PKGINFO (sans datahash, ajouté sauf `datahash: null`) ou texte brut. */
  readonly pkginfo?: readonly (readonly [string, string])[] | string;
  readonly datahash?: string | null;
  readonly scripts?: Readonly<Record<string, string>>;
  readonly controlEntries?: readonly TarSpec[];
  readonly dataFiles?: readonly TarSpec[];
  /** Membre signature : entrées tar (défaut : aucune signature). */
  readonly signature?: readonly TarSpec[];
  /** Membres gzip à la place de [signature, contrôle, données]. */
  readonly members?: (parts: { signature?: Uint8Array; control: Uint8Array; data: Uint8Array }) => Uint8Array[];
}

export function pkginfoText(lines: readonly (readonly [string, string])[], datahash: string | null): string {
  const all = datahash === null ? lines : [...lines, ['datahash', datahash] as const];
  return `# Generated by abuild\n${all.map(([key, value]) => `${key} = ${value}\n`).join('')}`;
}

export function buildApk(spec: ApkSpec = {}): Uint8Array {
  const dataFiles = spec.dataFiles ?? DEFAULT_DATA;
  const data = gzipSync(buildTar(dataFiles));
  const datahash = spec.datahash === undefined ? createHash('sha256').update(data).digest('hex') : spec.datahash;
  const pkginfo =
    typeof spec.pkginfo === 'string' ? spec.pkginfo : pkginfoText(spec.pkginfo ?? DEFAULT_PKGINFO, datahash);
  const controlEntries = spec.controlEntries ?? [
    { path: '.PKGINFO', data: pkginfo },
    ...Object.entries(spec.scripts ?? {}).map(([name, script]) => ({ path: name, data: script, mode: 0o755 })),
  ];
  const control = gzipSync(buildTar(controlEntries, { endMarker: false }));
  const signature = spec.signature ? gzipSync(buildTar(spec.signature, { endMarker: false })) : undefined;
  const parts = signature ? { signature, control, data } : { control, data };
  const members = spec.members ? spec.members(parts) : [...(signature ? [signature] : []), control, data];
  return Buffer.concat(members);
}

/** Entrée de signature abuild : `.SIGN.RSA256.<clé>.rsa.pub` contenant la signature (factice ici). */
export function signatureEntry(type = 'RSA256', keyName = 'equipe-6543.rsa.pub', size = 512): TarSpec {
  return { path: `.SIGN.${type}.${keyName}`, data: Buffer.alloc(size, 0x5a), mode: 0o644 };
}
